import csv,json,collections
gsm={s['accession']:s['title'] for s in json.load(open('gse.json'))['result']['200251671']['samples']}
rows=list(csv.DictReader(open('runinfo.csv')))
want={}
for r in rows:
    t=gsm.get(r['LibraryName'],'')
    p=t.split(':')
    if len(p)>6 and p[0]=='MOC_1430' and p[1] in ('col','water') and p[3]=='90min' and p[4]=='PA14':
        want.setdefault((p[1],p[6]),[]).append(r['Run'])
for k in sorted(want): print(k, want[k])
EOF

