const qs = ["bowtie2","fastp","deseq2","multiqc"];
const out = {};
for (const q of qs) {
  const r = await tools.call("galaxy_search_tools_by_name", {query:q});
  const items = (r.ok ? r.data.data : []) || [];
  out[q] = items.map(t=>t.id).filter(id=>id.includes(q)).slice(-3);
}
emit(out);

