const qs = ["Bowtie2","fastp","DESeq2","MultiQC"];
const out = {};
for (const q of qs) {
  const r = await tools.call("galaxy_search_tools_by_name", {query:q});
  if(!r.ok){ out[q]={err:r.error}; continue;}
  const items = r.data?.data ?? r.data ?? [];
  out[q] = Array.isArray(items) ? items.slice(0,4).map(t=>({id:t.id,v:t.version})) : items;
}
emit(out);

