const qs = ["fastp","DESeq2","MultiQC","Concatenate datasets","Column arrange","annotateMyIDs"];
const out = {};
for (const q of qs) {
  const r = await tools.call("galaxy_search_tools_by_name", {query:q});
  let d = r.data;
  if (d?.content?.[0]?.text) d = JSON.parse(d.content[0].text);
  const items = d?.data ?? [];
  out[q] = items.map(t=>t.id+"  ["+t.name+"]").slice(0,6);
}
emit(out);

for (const id of ["toolshed.g2.bx.psu.edu/repos/bgruening/text_processing/tp_cat/9.5+galaxy3"]) {
  const r = await tools.call("galaxy_get_tool_details", {tool_id:id, io_details:true});
  let d=r.data; if(d?.content?.[0]?.text) d=JSON.parse(d.content[0].text);
  const inp = d.data?.inputs ?? d.inputs;
  emit(JSON.stringify(inp).slice(0,1500));
}

const out={};
for (const id of ["__BUILD_LIST__","__ZIP_COLLECTION__","__APPLY_RULES__","__FILTER_FROM_FILE__"]) {
  const r = await tools.call("galaxy_get_tool_details", {tool_id:id, io_details:false});
  let d=r.data; if(d?.content?.[0]?.text) d=JSON.parse(d.content[0].text);
  out[id] = r.ok ? (d.data?.name ?? d.name ?? JSON.stringify(d).slice(0,200)) : String(r.error).slice(0,150);
}
emit(out);

