import json
d=json.load(open('main.json'))
def scan(wf,prefix=""):
    for k,st in wf.get('steps',{}).items():
        t=st.get('type')
        if t=='subworkflow':
            scan(st['subworkflow'], prefix+f"[{k}]")
        else:
            tid=st.get('tool_id') or ''
            if any(x in tid.lower() for x in ['featurecounts','rna_star','fastp','deseq2']):
                print("===",prefix,k,tid)
scan(d)
EOF

