function walk(ins,path){ let hits=[];
  for(const i of ins){
    const p=path?path+"|"+i.name:i.name;
    if(/SAindex|Nbases|genomeSA/i.test(i.name)) hits.push({p,type:i.type,label:i.label,value:i.value});
    if(i.cases) for(const c of i.cases) hits=hits.concat(walk(c.inputs||[],p+"|"+c.value));
    if(i.inputs) hits=hits.concat(walk(i.inputs,p));
  } return hits; }
emit(walk(inputs,""));

